<?php require_once __DIR__.'/../includes/bootstrap.php';require_once __DIR__.'/../includes/link_service.php';$u=require_auth();$link=owns_link((int)($_GET['id']??0),(int)$u['id']);if(!$link)fail(404,'Link not found','This link does not exist or is not yours.');$s=db()->prepare('SELECT DATE(clicked_at) day,COUNT(*) clicks FROM link_clicks WHERE short_link_id=? AND clicked_at >= DATE_SUB(CURDATE(),INTERVAL 29 DAY) GROUP BY DATE(clicked_at) ORDER BY day');$s->execute([$link['id']]);$daily=$s->fetchAll();$pageTitle='Analytics — LinkForge';require __DIR__.'/../includes/header.php';?><main class="container analytics"><a class="back" href="dashboard.php">← Back to dashboard</a><p class="eyebrow">LINK ANALYTICS</p><h1><?=e(short_url($link['code']))?></h1><p class="destination"><?=e($link['destination_url'])?></p><section class="stats"><article><span>Total clicks</span><strong><?=e((string)$link['click_count'])?></strong></article><article><span>Created</span><strong class="date"><?=e(date('M j, Y',strtotime($link['created_at'])))?></strong></article><article><span>Last clicked</span><strong class="date"><?= $link['last_clicked_at']?e(date('M j, Y',strtotime($link['last_clicked_at']))):'—' ?></strong></article><article><span>Expires</span><strong class="date"><?= $link['expires_at']?e(date('M j, Y',strtotime($link['expires_at']))):'Never' ?></strong></article></section><section class="panel"><h2>Clicks by date</h2><?php if(!$daily):?><p class="empty">No clicks yet. Share the link to begin tracking activity.</p><?php else:?><div class="chart" aria-label="Clicks in the last 30 days"><?php $max=max(array_column($daily,'clicks'));foreach($daily as $d):?><div class="bar-wrap"><span class="bar" style="height:<?=max(8,(int)round(180*$d['clicks']/$max))?>px" title="<?=e($d['day'])?>: <?=e((string)$d['clicks'])?> clicks"></span><small><?=e(date('M j',strtotime($d['day'])))?></small></div><?php endforeach?></div><?php endif?></section></main><?php require __DIR__.'/../includes/footer.php'; ?>
